// IngestServiceHandler is an implementation of the ingest.v1.IngestService service.
type IngestServiceHandler interface {
	// Searches upstream. Topics decide what the feed offers; search is how the
	// user goes looking for something the topics were never going to surface.
	Search(context.Context, *connect.Request[v1.SearchRequest]) (*connect.Response[v1.SearchResponse], error)
	// Creates the catalog row for a video found by search, so it can be opened
	// like any other. No media is fetched: pressing play does that.
	EnsureVideo(context.Context, *connect.Request[v1.EnsureVideoRequest]) (*connect.Response[v1.EnsureVideoResponse], error)
	// Reads one video's metadata upstream, writing nothing.
	//
	// Pasting a link into search points at exactly one video, so searching for
	// the text of its address is the wrong verb — it spends a counted upstream
	// request (see the note on Search) hunting for something already located.
	// This fetches that one video instead.
	//
	// It writes nothing on purpose: a pasted link and a search result are the
	// same act — "I saw this video elsewhere" — and a search result is written
	// only when it is opened. Two rules for one act is how they come to disagree.
	PreviewVideo(context.Context, *connect.Request[v1.PreviewVideoRequest]) (*connect.Response[v1.PreviewVideoResponse], error)
	// Rescans topics.yaml now instead of waiting for the timer.
	Refresh(context.Context, *connect.Request[v1.RefreshRequest]) (*connect.Response[v1.RefreshResponse], error)
	// Assigns YouTube's own category to videos that have none.
	//
	// Scans use flat listings, which carry no category, so everything they bring
	// in arrives without a topic and stays invisible to topic filters. Fetching
	// categories during a scan was tried and measured, and made scanning
	// unusable; this is the same work as a separate pass that runs when asked.
	// Returns as soon as the pass has started. Finishing takes hours — YouTube
	// throttles sustained metadata fetches — so progress is polled through
	// GetBackfillStatus rather than awaited.
	BackfillTopics(context.Context, *connect.Request[v1.BackfillTopicsRequest]) (*connect.Response[v1.BackfillTopicsResponse], error)
	GetBackfillStatus(context.Context, *connect.Request[v1.GetBackfillStatusRequest]) (*connect.Response[v1.GetBackfillStatusResponse], error)
	GetScanStatus(context.Context, *connect.Request[v1.GetScanStatusRequest]) (*connect.Response[v1.GetScanStatusResponse], error)
	// Resolves a directly playable upstream URL. This is what makes "click and
	// watch" feel instant; the URL is short-lived and must not be persisted.
	ResolveStream(context.Context, *connect.Request[v1.ResolveStreamRequest]) (*connect.Response[v1.ResolveStreamResponse], error)
	// Queues a download. Returns immediately; progress is polled through GetJob.
	Submit(context.Context, *connect.Request[v1.SubmitRequest]) (*connect.Response[v1.SubmitResponse], error)
	GetJob(context.Context, *connect.Request[v1.GetJobRequest]) (*connect.Response[v1.GetJobResponse], error)
	ListJobs(context.Context, *connect.Request[v1.ListJobsRequest]) (*connect.Response[v1.ListJobsResponse], error)
	CancelJob(context.Context, *connect.Request[v1.CancelJobRequest]) (*connect.Response[v1.CancelJobResponse], error)
	// Takes a finished job off the Activity page. Terminal states only: a job
	// still running is cancelled, not hidden.
	DismissJob(context.Context, *connect.Request[v1.DismissJobRequest]) (*connect.Response[v1.DismissJobResponse], error)
	// Dismisses every job with a given state, so the Activity page can be emptied
	// in one action rather than one row at a time.
	DismissJobs(context.Context, *connect.Request[v1.DismissJobsRequest]) (*connect.Response[v1.DismissJobsResponse], error)
	// Queues the same URL again. Most failures here are temporary — a rate limit,
	// a block that has lifted, a network that dropped — so trying again is worth
	// an action of its own rather than leaving "hide it" as the only one.
	RetryJob(context.Context, *connect.Request[v1.RetryJobRequest]) (*connect.Response[v1.RetryJobResponse], error)
	// What the scanner has been doing, newest first. Distinct from GetScanStatus,
	// which reports only the pass that has just run.
	ListScans(context.Context, *connect.Request[v1.ListScansRequest]) (*connect.Response[v1.ListScansResponse], error)
	// Deletes every scan row, so the Scand page clears in one action.
	ClearScans(context.Context, *connect.Request[v1.ClearScansRequest]) (*connect.Response[v1.ClearScansResponse], error)
	// Stops whatever transfer is running for a video. Called when a viewer leaves
	// the watch page: a copy nobody is waiting for is a request to YouTube nobody
	// is waiting for either, and too many of those get the address blocked.
	CancelVideoDownload(context.Context, *connect.Request[v1.CancelVideoDownloadRequest]) (*connect.Response[v1.CancelVideoDownloadResponse], error)
	// Brings new material into the library when the feed is running low. Metadata
	// only: nothing is downloaded until someone presses play.
	ExpandLibrary(context.Context, *connect.Request[v1.ExpandLibraryRequest]) (*connect.Response[v1.ExpandLibraryResponse], error)
	// A household member's own YouTube session.
	//
	// Write-only by design: there is no RPC that returns cookie content, because
	// a cookies.txt is a live Google session and the only thing that should ever
	// hold it is the yt-dlp command line being built for it.
	SetAccountCookies(context.Context, *connect.Request[v1.SetAccountCookiesRequest]) (*connect.Response[v1.SetAccountCookiesResponse], error)
	ListAccounts(context.Context, *connect.Request[v1.ListAccountsRequest]) (*connect.Response[v1.ListAccountsResponse], error)
	RemoveAccount(context.Context, *connect.Request[v1.RemoveAccountRequest]) (*connect.Response[v1.RemoveAccountResponse], error)
	ScanAccounts(context.Context, *connect.Request[v1.ScanAccountsRequest]) (*connect.Response[v1.ScanAccountsResponse], error)
	// Lists a channel's uploads straight from YouTube, paginated. The channel
	// page uses this rather than the local catalog so browsing a channel is not
	// limited to whatever a scan happened to bring in.
	ListChannelUploads(context.Context, *connect.Request[v1.ListChannelUploadsRequest]) (*connect.Response[v1.ListChannelUploadsResponse], error)
	// Fetches comments for a video from YouTube via yt-dlp. Returns every comment
	// in one call — yt-dlp's --write-comments has no pagination — so the gateway
	// batches them into catalog and the frontend paginates from there.
	FetchComments(context.Context, *connect.Request[v1.FetchCommentsRequest]) (*connect.Response[v1.FetchCommentsResponse], error)
}

